# The greenhouse of Crate Keeper from one list of rooms: each room's hedra command file
# (room0.txt .. room6.txt: a tiled bench, planter-box walls, sunk pads, bushes and pots), the
# room table that scene/game.as plays (written between its "// <rooms>" markers: the grid, where the
# room sits, its name, its par and an optimal solution for the demo), and the pars, found by a
# breadth-first search over (keeper cell, crate cells): par = the fewest keeper steps (pushes count
# as steps) that cover every pad. Run from models/env: /usr/bin/python3 make_env.py [--check]
#
# Grid legend: '#' planter wall, ' ' floor, '.' pad, '$' crate, '*' crate on a pad, '@' keeper,
# '-' nothing (the void around an odd-shaped bench). Row 0 is the far row (world -Z), column 0 the
# left column (world -X); a cell is 1 m. World X = room X + c - (W-1)/2, Z = room Z + r - (H-1)/2.
# The camera looks from +X +Z (yaw 45), so walls with floor behind them (at c-1 or r-1) are low.
import os, random, sys
from collections import deque

HERE = os.path.dirname(os.path.abspath(__file__))
GAME = os.path.join(HERE, "..", "..", "scene", "game.as")

ROOMS = [
    ("SEED SHELF", (0, 0), [
        "######",
        "#.   #",
        "#    #",
        "# #$ #",
        "#@   #",
        "######"]),
    ("FERN BAY", (10, 0), [
        "-######",
        "##  . #",
        "#  $  #",
        "# $#  #",
        "#@  . #",
        "#######"]),
    ("POTTING NOOK", (20, 0), [
        "-######",
        "##  ..#",
        "# $$  #",
        "# @#  #",
        "##   ##",
        "#######"]),
    ("TULIP ROW", (20, 10), [
        "########",
        "##     #",
        "#    $ #",
        "## $ $##",
        "#...  @#",
        "########"]),
    ("MOSS CORNER", (10, 10), [
        "-#######",
        "#    . #",
        "#  $#  #",
        "# # ..##",
        "#  $ $ #",
        "####@ ##",
        "-#######"]),
    ("ORCHID LOFT", (0, 10), [
        "########",
        "#   #..#",
        "# $ $  #",
        "#  # $ #",
        "# .  # #",
        "# ###@ #",
        "########"]),
    ("MOON GARDEN", (0, 20), [
        "########",
        "#.  #  #",
        "#.$$ $ #",
        "#. #   #",
        "#  #$  #",
        "#  .@###",
        "########"]),
]

WALL_LOW, WALL_HIGH, SKIRT = 0.3, 0.55, 0.3
DIRS = [(0, -1, "U"), (1, 0, "R"), (0, 1, "D"), (-1, 0, "L")]


def parse(rows):
    walls, pads, crates, floor, keeper = set(), set(), set(), set(), None
    for r, line in enumerate(rows):
        for c, ch in enumerate(line):
            if ch == "#":
                walls.add((c, r))
            elif ch in " .$*@+":
                floor.add((c, r))
            if ch in ".*+":
                pads.add((c, r))
            if ch in "$*":
                crates.add((c, r))
            if ch in "@+":
                keeper = (c, r)
    return walls, pads, crates, floor, keeper


def solve(rows):
    """Breadth-first search: the fewest steps (upper case a walk, lower case a push)."""
    walls, pads, crates, floor, keeper = parse(rows)
    start = (keeper, frozenset(crates))
    prev = {start: None}
    q = deque([start])
    while q:
        s = q.popleft()
        p, cs = s
        if cs == pads:
            path = []
            while prev[s] is not None:
                s, m = prev[s]
                path.append(m)
            return "".join(reversed(path)), len(prev)
        for dx, dy, n in DIRS:
            np_ = (p[0] + dx, p[1] + dy)
            if np_ not in floor:
                continue
            ncs = cs
            if np_ in cs:
                bp = (np_[0] + dx, np_[1] + dy)
                if bp not in floor or bp in cs:
                    continue
                ncs = (cs - {np_}) | {bp}
                n = n.lower()
            ns = (np_, ncs)
            if ns not in prev:
                prev[ns] = (s, n)
                q.append(ns)
    return None, len(prev)


def cell_expr(cells, W, H):
    """a hedra `select where` expression matching the face centres of these cells (hedra y = -row)"""
    terms = []
    for c, r in sorted(cells):
        x = c - (W - 1) / 2
        y = -(r - (H - 1) / 2)
        terms.append(f"(abs(pos.x - {x:.2f}) < 0.3 && abs(pos.y - {y:.2f}) < 0.3)")
    return " || ".join(terms)


def room_txt(i, name, rows):
    W, H = len(rows[0]), len(rows)
    walls, pads, crates, floor, keeper = parse(rows)
    void = {(c, r) for r in range(H) for c in range(W) if rows[r][c] == "-"}
    low = {w for w in walls if (w[0] - 1, w[1]) in floor or (w[0], w[1] - 1) in floor}
    high = walls - low
    rng = random.Random(100 + i)
    L = [f"# Room {i + 1}, {name.title()}: generated by make_env.py from its grid (do not edit by hand).",
         "# A tiled bench (a violet and teal slate checker, white pads sunk in), violet planter-box walls under mint hedges (low where floor lies",
         "# behind them, so the camera sees over), a violet skirt; bushes, flowers and pots on the walls.",
         "# Up Z, the room's far row towards +Y; origin at the room's centre, the floor's top at z 0.",
         "new",
         "material new Tile --base-color 0.392 0.380 0.761 --no-slot",
         "material new TileB --base-color 0.169 0.663 0.706 --no-slot",
         "material new Pad --base-color 0.941 0.965 0.910 --no-slot",
         "material new Planter --base-color 0.392 0.380 0.761 --no-slot",
         "material new Hedge --base-color 0.576 0.831 0.710 --no-slot",
         "material new Bench --base-color 0.392 0.380 0.761 --no-slot",
         "material new Bush --base-color 0.169 0.663 0.706 --no-slot",
         "material new Bloom --base-color 0.890 0.604 0.675 --no-slot",
         "material new Pot --base-color 0.769 0.365 0.624 --no-slot",
         f"add mesh grid --name Room --size 1 --x-subdivisions {W} --y-subdivisions {H} --location 0 0 0",
         f"scale {W} {H} 1",
         "apply --scale",
         "material assign Tile",
         "mode edit",
         "select mode face"]
    if void:
        L += [f'select face where "{cell_expr(void, W, H)}"', "delete only-faces"]
    L += ['select face where "(floor(pos.x + 20.25) + floor(pos.y + 20.25)) % 2 == 0"',
          "material assign TileB",
          f'select face where "{cell_expr(pads, W, H)}"',
          "inset 0.14",
          "material assign Pad",
          f'select face where "{cell_expr(walls, W, H)}"',
          "material assign Planter"]
    if high:
        L += [f'select face where "{cell_expr(high, W, H)}"', f"extrude 0 0 {WALL_HIGH}", "material assign Hedge"]
    if low:
        L += [f'select face where "{cell_expr(low, W, H)}"', f"extrude 0 0 {WALL_LOW}", "material assign Hedge"]
    L += ["select non-manifold",
          f"extrude --only-edges 0 0 {-SKIRT}",
          'select face where "pos.z < -0.05"',
          "material assign Bench",
          'select face where "1"',
          "normals recalculate",
          # faces turned away from the camera (world -X, -Z) are never seen: drop their splats
          'select face where "normal.x < -0.9 || normal.y > 0.9 || normal.z < -0.9"',
          "delete only-faces",
          "mode object"]
    # dressing on the wall tops: bushes (some flowering) and a pot or two, seeded per room
    names = []
    tops = sorted(walls)
    rng.shuffle(tops)
    k = 0
    for (c, r) in tops[: max(4, len(tops) // 3)]:
        x = c - (W - 1) / 2 + rng.uniform(-0.12, 0.12)
        y = -(r - (H - 1) / 2) + rng.uniform(-0.12, 0.12)
        z = WALL_LOW if (c, r) in low else WALL_HIGH
        if (c, r) in low and rng.random() < 0.6:
            continue                       # keep the low front walls mostly clear: they frame the floor
        if k % 4 == 3:
            L += [f"add mesh cone --name Pot{k} --vertices 8 --radius1 0.15 --radius2 0.2 --depth 0.26 --location {x:.2f} {y:.2f} {z + 0.13:.2f}",
                  "material assign Pot",
                  f"add mesh ico-sphere --name PotLeaf{k} --subdivisions 1 --radius 0.24 --location {x:.2f} {y:.2f} {z + 0.38:.2f}",
                  "scale 1 1 0.8", "apply --scale", "material assign Bush",
                  f"add mesh ico-sphere --name PotBloom{k} --subdivisions 1 --radius 0.09 --location {x + 0.08:.2f} {y - 0.1:.2f} {z + 0.52:.2f}",
                  "material assign Bloom"]
            names += [f"Pot{k}", f"PotLeaf{k}", f"PotBloom{k}"]
        else:
            rad = rng.uniform(0.26, 0.34)
            L += [f"add mesh ico-sphere --name Bush{k} --subdivisions 1 --radius {rad:.2f} --location {x:.2f} {y:.2f} {z + 0.08:.2f}",
                  "scale 1 1 0.62", "apply --scale", "material assign Bush"]
            names.append(f"Bush{k}")
            if rng.random() < 0.5:
                L += [f"add mesh ico-sphere --name Bloom{k} --subdivisions 1 --radius 0.08 --location {x + rng.uniform(-0.1, 0.1):.2f} {y - 0.08:.2f} {z + 0.08 + rad * 0.62:.2f}",
                      "material assign Bloom"]
                names.append(f"Bloom{k}")
        k += 1
    L += ["select all", "shade flat", "inspect stats", f"export room{i}.glb"]
    return "\n".join(L) + "\n"


def table(results):
    """the room table for scene/game.as"""
    grids, ws, hs, xs, zs, pars, sols, names, offs = [], [], [], [], [], [], [], [], []
    off = 0
    for (name, (X, Z), rows), (sol, _) in zip(ROOMS, results):
        W, H = len(rows[0]), len(rows)
        grids.append("".join(rows))
        ws.append(W); hs.append(H); xs.append(X); zs.append(Z)
        pars.append(len(sol)); sols.append(sol); names.append(name); offs.append(off)
        off += W * H
    q = lambda s: '"' + s + '"'
    out = ["// <rooms> generated by models/env/make_env.py from its ROOMS list: do not edit by hand",
           "// grid legend: '#' wall, ' ' floor, '.' pad, '$' crate, '*' crate on a pad, '@' keeper, '-' void",
           f"const NROOM: i32 = {len(ROOMS)};",
           f"const ROOM_GRID: string = {q(''.join(grids))};",
           f"const ROOM_OFF: StaticArray<i32> = [{', '.join(map(str, offs))}];",
           f"const ROOM_W: StaticArray<i32> = [{', '.join(map(str, ws))}];",
           f"const ROOM_H: StaticArray<i32> = [{', '.join(map(str, hs))}];",
           f"const ROOM_X: StaticArray<f64> = [{', '.join(f'{x:.1f}' for x in xs)}];",
           f"const ROOM_Z: StaticArray<f64> = [{', '.join(f'{z:.1f}' for z in zs)}];",
           f"const ROOM_PAR: StaticArray<i32> = [{', '.join(map(str, pars))}];",
           f"const ROOM_NAME: StaticArray<string> = [{', '.join(q(n) for n in names)}];",
           "// an optimal solution per room (BFS; upper case a walk, lower case a push): the demo's plan",
           f"const ROOM_SOL: StaticArray<string> = [{', '.join(q(s) for s in sols)}];",
           "// </rooms>"]
    return "\n".join(out)


def main():
    results = []
    for i, (name, pos, rows) in enumerate(ROOMS):
        assert len({len(r) for r in rows}) == 1, name
        sol, n = solve(rows)
        assert sol, f"room {i + 1} {name} cannot be solved"
        walls, pads, crates, floor, keeper = parse(rows)
        assert len(pads) == len(crates) <= 4, name
        print(f"room {i + 1} {name:13s} {len(rows[0])}x{len(rows)} crates {len(crates)}  par {len(sol):3d}"
              f"  pushes {sum(m.islower() for m in sol):2d}  states {n:6d}  {sol}")
        results.append((sol, n))
    print("total par", sum(len(s) for s, _ in results))
    if "--check" in sys.argv:
        return
    for i, (name, pos, rows) in enumerate(ROOMS):
        with open(os.path.join(HERE, f"room{i}.txt"), "w") as f:
            f.write(room_txt(i, name, rows))
    src = open(GAME).read()
    a, b = src.index("// <rooms>"), src.index("// </rooms>") + len("// </rooms>")
    open(GAME, "w").write(src[:a] + table(results) + src[b:])
    print("wrote room0..%d.txt and the room table in scene/game.as" % (len(ROOMS) - 1))


if __name__ == "__main__":
    main()
